import{_ as r,o as a,c as t,a2 as o}from"./chunks/framework.CqGPl1zp.js";const b=JSON.parse('{"title":"【v2026-08】","description":"","frontmatter":{},"headers":[],"relativePath":"changelog/2026-08.md","filePath":"changelog/2026-08.md","lastUpdated":null}'),i={name:"changelog/2026-08.md"};function l(n,e,c,d,h,f){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="【v2026-08】" tabindex="-1">【v2026-08】 <a class="header-anchor" href="#【v2026-08】" aria-label="Permalink to &quot;【v2026-08】&quot;">​</a></h1><h2 id="新增-hrm-人力资源管理系统、fms-财务管理系统-支持独立手机端操作" tabindex="-1">新增 HRM 人力资源管理系统、FMS 财务管理系统，支持独立手机端操作 <a class="header-anchor" href="#新增-hrm-人力资源管理系统、fms-财务管理系统-支持独立手机端操作" aria-label="Permalink to &quot;新增 HRM 人力资源管理系统、FMS 财务管理系统，支持独立手机端操作&quot;">​</a></h2><p>本月概要：</p><ul><li>【HRM】完成人力资源管理模块整合，补齐对应的后端工程与业务能力，并支持 Admin 移动端。</li><li>【FMS】完成财务管理模块整合，补齐对应的后端工程与业务能力，并支持 Admin 移动端。</li><li>【稳定性】修复工作流、Vben5.0、支付及基础设施等模块的用户反馈问题，增强系统稳定性。</li></ul><h3 id="📈-statistic" tabindex="-1">📈 Statistic <a class="header-anchor" href="#📈-statistic" aria-label="Permalink to &quot;📈 Statistic&quot;">​</a></h3><ul><li>总代码行数：552658</li><li>源码代码行数：353795</li><li>注释行数：118243</li><li>单元测试用例数：3299</li></ul><h3 id="🚀-新增功能" tabindex="-1">🚀 新增功能 <a class="header-anchor" href="#🚀-新增功能" aria-label="Permalink to &quot;🚀 新增功能&quot;">​</a></h3><p>后端框架专区：</p><ul><li>【优化】扩展 <code>LambdaQueryWrapperX</code> 的 <code>exists</code>、<code>notExists</code>、<code>and</code>、<code>or</code>、<code>nested</code>、<code>not</code> 链式查询方法，保持自定义 Wrapper 类型返回，由 <a href="https://gitee.com/wuKongD" target="_blank" rel="noreferrer">@wuKongD</a> 贡献 <a href="https://gitee.com/zhijiantianya/yudao-cloud/pulls/265" target="_blank" rel="noreferrer">#265</a></li></ul><p>HRM 人力资源专区：</p><ul><li>【新增】HRM 人力资源管理系统，支持 admin 手机端，由 <a href="https://github.com/YunaiV" target="_blank" rel="noreferrer">@芋道源码</a> 贡献 <a href="https://github.com/YunaiV/ruoyi-vue-pro/commit/e2fa61b7e59152e89532c0c461a926e8c1368833" target="_blank" rel="noreferrer">e2fa61b7</a></li></ul><p>FMS 财务管理专区：</p><ul><li>【新增】FMS 财务管理系统，支持 admin 手机端，，由 <a href="https://github.com/YunaiV" target="_blank" rel="noreferrer">@芋道源码</a> 贡献 <a href="https://github.com/YunaiV/ruoyi-vue-pro/commit/0628a46b3cf172fa3423bf64f23293d8d3357ec1" target="_blank" rel="noreferrer">0628a46b</a></li></ul><p>支付模块专区：</p><ul><li>【新增】支付宝小程序支付，支持 <code>buyer_open_id</code>、<code>buyer_id</code> 和证书模式下单，并补充对应单元测试，由 <a href="https://github.com/graypxl" target="_blank" rel="noreferrer">@graypxl</a> 贡献 <a href="https://github.com/YunaiV/ruoyi-vue-pro/pull/1194" target="_blank" rel="noreferrer">#1194</a></li></ul><p>IoT 物联网专区：</p><ul><li>【新增】补齐 OTA 固件列表删除功能，存在进行中的升级任务时禁止删除固件，由 <a href="https://gitee.com/pandadx" target="_blank" rel="noreferrer">@pandadx</a> 贡献 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro/pulls/1579" target="_blank" rel="noreferrer">!1579</a></li></ul><p>Vue2 管理后台专区：</p><ul><li>【优化】Vue2 管理后台 BPM 工作流整体对齐 Vue3 + Element Plus 版本，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 贡献 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vue2/commit/e4d0a26a8ae1e2fc51f543163550f8b05588beb1" target="_blank" rel="noreferrer">e4d0a26</a> ，对应 &lt;<a href="https://t.zsxq.com/7BSE6" target="_blank" rel="noreferrer">https://t.zsxq.com/7BSE6</a> &gt;</li></ul><p>Vue3 管理后台专区：</p><ul><li>【优化】优化代码生成界面预览代码对话框布局，减少不必要的内边距并避免右侧代码区域超出视口，由 <a href="https://gitee.com/fc88804" target="_blank" rel="noreferrer">@fc88804</a> 贡献 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vue3/pulls/903" target="_blank" rel="noreferrer">!903</a></li></ul><h3 id="🐞-问题修复" tabindex="-1">🐞 问题修复 <a class="header-anchor" href="#🐞-问题修复" aria-label="Permalink to &quot;🐞 问题修复&quot;">​</a></h3><p>后端框架专区：</p><ul><li>【修复】修复阿里云 OSS、七牛云使用自定义域名时前端直传签名地址生成错误的问题，签名节点改用服务商 endpoint，并补充对应单元测试，由 <a href="https://gitee.com/situjunjie" target="_blank" rel="noreferrer">@situjunjie</a> 贡献 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro/pulls/1588" target="_blank" rel="noreferrer">!1588</a> ，对应 <a href="https://t.zsxq.com/qYxXZ" target="_blank" rel="noreferrer">https://t.zsxq.com/qYxXZ</a></li><li>【修复】邮件模板 HTML 代码块内容包含 <code>$</code> 或反斜杠时，<code>MailTemplateServiceImpl</code> 使用正则替换可能抛出 <code>IllegalArgumentException</code> 的问题，通过 <code>Matcher.quoteReplacement</code> 安全处理替换内容，由 <a href="https://github.com/nemisolv" target="_blank" rel="noreferrer">@nemisolv</a> 贡献 <a href="https://github.com/YunaiV/ruoyi-vue-pro/pull/1204" target="_blank" rel="noreferrer">#1204</a></li><li>【修复】<code>WebProperties</code> 嵌套配置属性未正确进行级联校验的问题，为 <code>appApi</code>、<code>adminApi</code>、<code>adminUi</code> 增加 <code>@Valid</code> 校验，由 <a href="https://github.com/nemisolv" target="_blank" rel="noreferrer">@nemisolv</a> 贡献 <a href="https://github.com/YunaiV/ruoyi-vue-pro/pull/1187" target="_blank" rel="noreferrer">#1187</a></li><li>【修复】单体版、微服务版 <code>GlobalExceptionHandler</code> 处理携带成功码（<code>code = 0</code>）的 <code>ServiceException</code> 时，避免继续调用 <code>CommonResult.error</code> 抛出异常，统一返回系统异常，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro/commit/d7411081c76149145b5b6996f16522a7aa7c892e" target="_blank" rel="noreferrer">单体版 d7411081</a> 、<a href="https://gitee.com/zhijiantianya/yudao-cloud/commit/4658bca261c1006bb5cd2e203d3c1ea4841ea569" target="_blank" rel="noreferrer">微服务版 4658bca2</a> ，对应 <a href="https://github.com/YunaiV/ruoyi-vue-pro/issues/1196" target="_blank" rel="noreferrer">#1196</a></li><li>【修复】单体版、微服务版在多 <code>SecurityFilterChain</code> 场景下，<code>TokenAuthenticationFilter</code> 被 Spring Boot 注册为 Servlet 全局过滤器，导致独立安全链请求被越界处理的问题；通过禁用 <code>FilterRegistrationBean</code> 自动注册，确保过滤器仅由 Spring Security FilterChain 管理，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro/commit/809d6aaa9426ef20dc964dd3ec6512051f2048d9" target="_blank" rel="noreferrer">单体版 809d6aaa</a> 、<a href="https://gitee.com/zhijiantianya/yudao-cloud/commit/1731933a93160263b8f23b9f6550c987ccd77ca8" target="_blank" rel="noreferrer">微服务版 1731933a</a> ，对应 <a href="https://github.com/YunaiV/ruoyi-vue-pro/issues/1198" target="_blank" rel="noreferrer">#1198</a></li><li>【修复】修复 BPM 流程发起人部门负责人获取错误的问题，优先使用流程变量中的发起人编号查询部门，避免错误使用当前登录用户，由 <a href="https://gitee.com/zyy0604" target="_blank" rel="noreferrer">@周洋洋</a> 贡献 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro/commit/922c8b834e7792befbb1564de44cb6820bcf6dc9" target="_blank" rel="noreferrer">922c8b83</a> ，对应 <a href="https://gitee.com/zhijiantianya/yudao-cloud/issues/IK8441" target="_blank" rel="noreferrer">IK8441</a></li></ul><p>支付模块专区：</p><ul><li>【修复】修复微信支付使用临时证书文件时，系统清理临时文件导致支付不定时不可用的问题，改用微信支付 SDK 的证书内容配置，由 <a href="https://gitee.com/IDontDrive" target="_blank" rel="noreferrer">@IDontDrive</a> 贡献 <a href="https://gitee.com/zhijiantianya/yudao-cloud/pulls/263" target="_blank" rel="noreferrer">#263</a></li><li>【修复】修复支付宝支付回调中渠道用户 ID 获取错误的问题，优先使用 <code>buyer_open_id</code>，兼容 <code>buyer_id</code>，并更新渠道用户编号说明，由 <a href="https://gitee.com/wuKongD" target="_blank" rel="noreferrer">@wuKongD</a> 贡献 <a href="https://gitee.com/zhijiantianya/yudao-cloud/pulls/266" target="_blank" rel="noreferrer">#266</a></li></ul><p>MES 制造执行专区：</p><ul><li>【修复】修复排班计划倒班字段联动清理及排班生成异常：单白班不倒班，非按天倒班清理倒班天数，并校验倒班参数，由 <a href="https://gitee.com/hnnuWangli" target="_blank" rel="noreferrer">@hnnuWangli</a> 贡献 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro/pulls/1583" target="_blank" rel="noreferrer">!1583</a></li></ul><p>IoT 物联网专区：</p><ul><li>【修复】IoT 设备消息发送接口权限标识错误，将 Controller 的 <code>iot:device:message-end</code> 统一为菜单 SQL 的 <code>iot:device:message-send</code>，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro/commit/856953352f5f4fd264a7f29b28328aac8da326ec" target="_blank" rel="noreferrer">8569533</a> ，对应 <a href="https://t.zsxq.com/9eFK5" target="_blank" rel="noreferrer">https://t.zsxq.com/9eFK5</a></li></ul><p>Vben5.0 管理后台专区：</p><ul><li>【修复】Vben5.0 管理后台 web-antd、web-antdv-next、web-ele 流程图查看器初始化时序问题，由 <a href="https://gitee.com/zyy0604" target="_blank" rel="noreferrer">@周洋洋</a> 贡献 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vue3/pulls/898" target="_blank" rel="noreferrer">!898</a> ，同步修复提交 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/commit/1573e9ce3610eb8be00a9b130dc7dfa024b38287" target="_blank" rel="noreferrer">1573e9ce3</a></li><li>【修复】Vben5.0 管理后台 BPM 流程发起页流程卡片空白，以及三端流程搜索、分类分组和表单变量清理不一致的问题，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/commit/a66bfc1d55f51ee68fa4b27f34f3a29091021312" target="_blank" rel="noreferrer">a66bfc1d</a> ，对应 <a href="https://t.zsxq.com/PR6Zd" target="_blank" rel="noreferrer">https://t.zsxq.com/PR6Zd</a></li><li>【修复】Vben5.0 管理后台 web-ele AI 聊天角色知识库、工具和 MCP 选择器无法多选的问题，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/commit/7810113aa2f97396c88be59995dd8c46c2203e7b" target="_blank" rel="noreferrer">7810113a</a> ，对应 <a href="https://t.zsxq.com/EVBwh" target="_blank" rel="noreferrer">https://t.zsxq.com/EVBwh</a></li><li>【修复】Vue3、Vben5.0 管理后台 HRM 考勤班次与每日明细查询的时间参数补齐时分秒，避免后端 <code>LocalDateTime</code> 解析失败，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vue3/commit/cb46b231419b030ca14d884a0da527c57b522d32" target="_blank" rel="noreferrer">Vue3 cb46b231</a> 、<a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/commit/816c71b28d902347d12a13535706ad3f1a7ddb42" target="_blank" rel="noreferrer">Vben5.0 816c71b28</a> ，对应 <a href="https://t.zsxq.com/aSB5X" target="_blank" rel="noreferrer">https://t.zsxq.com/aSB5X</a></li><li>【修复】Vben5.0 管理后台 Ant Design Vue、Element Plus、Ant Design Vue Next、Naive UI、TDesign 五端的 S3 文件配置 PathStyle 字段命名与后端不一致的问题，统一使用 <code>enablePathStyleAccess</code>，确保配置字段契约一致，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/commit/ff2050e90b416d08be510359dde904ce65b90821" target="_blank" rel="noreferrer">ff2050e90</a> ，对应 <a href="https://t.zsxq.com/H4WtU" target="_blank" rel="noreferrer">https://t.zsxq.com/H4WtU</a></li><li>【修复】Vben5.0 管理后台 web-antd、web-antdv-next、web-ele 的 IoT 数据规则数据源弹窗取消后再次打开可能报错的问题，改用 VXE 实际行对象绑定并移除关闭阶段异步清空，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/commit/8342ff233815375ebc9e98054f33f62887df53fd" target="_blank" rel="noreferrer">8342ff2</a> ，对应 <a href="https://t.zsxq.com/9eFK5" target="_blank" rel="noreferrer">https://t.zsxq.com/9eFK5</a></li><li>【修复】Vben5.0 管理后台 BPM 流程监听表单编辑回填时事件、值被清空，以及 Ant Design Vue、Ant Design Vue Next 流程设计器更新名称、标识传递事件对象的问题，由 <a href="https://gitee.com/jikemaimai" target="_blank" rel="noreferrer">@etexxk</a> 贡献 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/pulls/385" target="_blank" rel="noreferrer">!385</a> ，合并提交 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/commit/7f45fb54095da93b045eb8078b9b7cfab901fa34" target="_blank" rel="noreferrer">7f45fb5</a></li><li>【修复】Vben5.0 管理后台 web-antd、web-antdv-next、web-ele 公众号草稿封面与永久素材上传未携带正确公众号账号的问题，并阻止缺少封面的图文提交，由 <a href="https://github.com/izhaong" target="_blank" rel="noreferrer">@izhaong</a> 贡献 <a href="https://github.com/yudaocode/yudao-ui-admin-vben/pull/397" target="_blank" rel="noreferrer">#397</a> ，合并提交 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/commit/cb4cba3fed10a7fb09eb66a89cbb4646abc5b096" target="_blank" rel="noreferrer">cb4cba3fe</a></li><li>【修复】Vben5.0 管理后台 web-ele MES 选择弹窗、子表弹窗及条码详情弹窗被父级 <code>Modal</code> 裁剪的问题，统一增加 <code>append-to-body</code>，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/commit/0c08089dd89f4606ffeb499154229b5f034eba29" target="_blank" rel="noreferrer">0c08089dd</a> 、<a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/commit/4a671d08604fd401aace7a2523f285986fe53510" target="_blank" rel="noreferrer">4a671d086</a> ，对应 <a href="https://t.zsxq.com/8xh0S" target="_blank" rel="noreferrer">https://t.zsxq.com/8xh0S</a></li></ul><h3 id="🔨-dependency-upgrades" tabindex="-1">🔨 Dependency Upgrades <a class="header-anchor" href="#🔨-dependency-upgrades" aria-label="Permalink to &quot;🔨 Dependency Upgrades&quot;">​</a></h3><ul><li>【升级】mybatis-plus from 3.5.16 to 3.5.17</li><li>【升级】mybatis-plus-join from 1.5.7 to 1.5.9</li><li>【升级】easy-trans 按 Spring Boot 版本升级为 SB2 2.3.6、SB3 3.1.8、SB4 4.0.2</li><li>【升级】redisson from 4.6.1 to 4.7.0</li><li>【升级】taos-jdbcdriver from 3.8.4 to 3.9.0</li><li>【升级】opentelemetry from 1.39.0 to 1.65.0</li><li>【升级】jedis-mock from 1.1.15 to 1.1.18</li><li>【升级】hutool-all from 5.8.46 to 5.8.47</li><li>【升级】aviator from 5.3.3 to 5.4.4</li><li>【升级】fastjson2 from 2.0.63 to 2.0.64</li><li>【升级】guava from 33.6.0-jre to 33.7.1-jre</li><li>【升级】jsch from 2.28.3 to 2.28.7</li><li>【升级】jsoup from 1.22.2 to 1.23.2</li><li>【升级】netty from 4.2.15.Final to 4.2.17.Final</li><li>【升级】AWS SDK S3 from 2.46.17 to 2.54.7</li><li>【升级】支付宝 SDK from 4.40.865.ALL to 4.40.978.ALL</li><li>【升级】微信 Java SDK from 4.8.4-20260623.211820 to 4.8.6-20260825.155844</li><li>【升级】JimuReport / JimuBI：SB3/SB4 from 2.3.4/2.3.2 to 2.5.1/2.5.0，SB2 保持 2.3.4/2.3.2</li></ul>',34)])])}const m=r(i,[["render",l]]);export{b as __pageData,m as default};
